/**
 * Concatenates the migration set into one file that can be pasted into the
 * Supabase SQL editor.
 *
 * `supabase db push` is the better route when you have the database password.
 * This exists so the schema can be applied with dashboard access alone.
 */
import { readdirSync, readFileSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';

const root = process.cwd();
const migrationsDir = join(root, 'supabase', 'migrations');

const files = readdirSync(migrationsDir).filter((f) => f.endsWith('.sql')).sort();

const header = `-- =============================================================================
-- Cloud Kitchen -- complete schema
-- =============================================================================
-- Generated from supabase/migrations by scripts/build-bundle.mjs.
-- Do not edit this file: edit the migrations and regenerate.
--
-- Apply by pasting into the Supabase SQL editor, or run:
--   npx supabase db push
--
-- Files included, in order:
${files.map((f) => `--   ${f}`).join('\n')}
-- =============================================================================

`;

const body = files
  .map(
    (file) =>
      `\n-- >>> ${file} ${'='.repeat(Math.max(0, 60 - file.length))}\n\n` +
      readFileSync(join(migrationsDir, file), 'utf8').trimEnd() +
      '\n',
  )
  .join('\n');

writeFileSync(join(root, 'supabase', 'schema.sql'), header + body, 'utf8');

const lines = (header + body).split('\n').length;
console.log(`Wrote supabase/schema.sql (${files.length} migrations, ${lines} lines)`);
